import{_ as e,o as n,c as s,a2 as o}from"./chunks/framework.BZO4qERu.js";const h=JSON.parse('{"title":"悬浮窗 (Floaty)","description":"","frontmatter":{},"headers":[],"relativePath":"floaty.md","filePath":"floaty.md","lastUpdated":1780845803000}'),t={name:"floaty.md"};function i(d,a,p,l,c,w){return n(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="悬浮窗-floaty" tabindex="-1">悬浮窗 (Floaty)</h1><h2 id="_6-7-0-源码校对" tabindex="-1">6.7.0 源码校对</h2><p>本页已按 AutoJs6 <code>6.7.0</code> (<code>ed3eb10e88db5a8425fd94bdddefa4176e5e1c94</code>) 对照以下源码路径校对:</p><ul><li><code>app/src/main/java/org/autojs/autojs/runtime/ScriptRuntime.kt</code></li><li><code>app/src/main/java/org/autojs/autojs/runtime/api/augment/floaty/Floaty.kt</code></li><li><code>app/src/main/java/org/autojs/autojs/runtime/api/Floaty.kt</code></li><li><code>app/src/main/java/org/autojs/autojs/core/floaty/BaseResizableFloatyWindow.kt</code></li><li><code>app/src/main/java/org/autojs/autojs/core/floaty/RawWindow.kt</code></li><li><code>app/src/main/java/org/autojs/autojs/permission/DisplayOverOtherAppsPermission.kt</code></li></ul><p>运行时中 <code>floaty</code> / <code>$floaty</code> 由 augment 注入. 当前公开入口包括 <code>window</code>, <code>rawWindow</code>, <code>hasPermission</code>, <code>requestPermission</code>, <code>ensurePermission</code>, <code>closeAll</code>, <code>getClip</code>.</p><p>Rhino 公开入口的 <code>window(layout)</code> / <code>rawWindow(layout)</code> 只接受 XML / XML 字符串布局, 源码会从 <code>XMLObject</code> / <code>XMLList</code> 或字符串构建布局; 不接受已创建的 Android <code>View</code> 对象.</p><p>创建悬浮窗前会检查并等待悬浮窗权限, 最多约 60 秒; <code>ensurePermission()</code> 在无权限时直接抛错. <code>getClip(maxDelayAfterWindowReady?)</code> 会借助悬浮窗在较新 Android 系统上读取剪贴板, 默认最大等待 <code>500ms</code>.</p><p><code>window</code> 返回可调整窗口, <code>rawWindow</code> 返回原始窗口. 两者共有 <code>setPosition</code>, <code>setSize</code>, <code>requestFocus</code>, <code>disableFocus</code>, <code>close</code>, <code>exitOnClose</code> 和 <code>x</code>, <code>y</code>, <code>width</code>, <code>height</code>; <code>rawWindow</code> 额外公开 <code>setTouchable</code>, <code>window</code> 额外公开调整开关相关属性 / setter.</p><p>floaty模块提供了悬浮窗的相关函数, 可以在屏幕上显示自定义悬浮窗, 控制悬浮窗大小、位置等.</p><p>悬浮窗在脚本停止运行时会自动关闭, 因此, 要保持悬浮窗不被关闭, 可以用一个空的setInterval来实现, 例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setInterval(()=&gt;{}, 1000);</span></span></code></pre></div><h2 id="floaty-window-layout" tabindex="-1">floaty.window(layout)</h2><ul><li><code>layout</code> {xml} | {string} 悬浮窗界面的 XML 或 XML 字符串</li></ul><p>指定悬浮窗的布局, 创建并<strong>显示</strong>一个悬浮窗, 返回一个<code>FloatyWindow</code>对象.</p><p>该悬浮窗自带关闭、调整大小、调整位置按键, 可根据需要调用<code>setAdjustEnabled()</code>函数来显示或隐藏.</p><p>其中 layout 参数可以是 XML 布局或 XML 字符串, 更多信息参见 ui 模块的说明.</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var w = floaty.window(</span></span>
<span class="line"><span>    &lt;frame gravity=&quot;center&quot;&gt;</span></span>
<span class="line"><span>        &lt;text id=&quot;text&quot;&gt;悬浮文字&lt;/text&gt;</span></span>
<span class="line"><span>    &lt;/frame&gt;</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>setTimeout(()=&gt;{</span></span>
<span class="line"><span>    w.close();</span></span>
<span class="line"><span>}, 2000);</span></span></code></pre></div><p>这段代码运行后将会在屏幕上显示悬浮文字, 并在两秒后消失.</p><p>另外, 因为脚本运行的线程不是UI线程, 而所有对控件的修改操作需要在UI线程执行, 此时需要用<code>ui.run</code>, 例如:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ui.run(function(){</span></span>
<span class="line"><span>    w.text.setText(&quot;文本&quot;);</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>有关返回的<code>FloatyWindow</code>对象的说明, 参见下面的<code>FloatyWindow</code>章节.</p><h2 id="floaty-rawwindow-layout" tabindex="-1">floaty.rawWindow(layout)</h2><ul><li><code>layout</code> {xml} | {string} 悬浮窗界面的 XML 或 XML 字符串</li></ul><p>指定悬浮窗的布局, 创建并<strong>显示</strong>一个原始悬浮窗, 返回一个<code>FloatyRawWindow</code>对象.</p><p>与<code>floaty.window()</code>函数不同的是, 该悬浮窗不会增加任何额外设施（例如调整大小、位置按钮）, 您可以根据自己需要编写任何布局.</p><p>而且, 该悬浮窗支持完全全屏, 可以覆盖状态栏, 因此可以做护眼模式之类的应用.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var w = floaty.rawWindow(</span></span>
<span class="line"><span>    &lt;frame gravity=&quot;center&quot;&gt;</span></span>
<span class="line"><span>        &lt;text id=&quot;text&quot;&gt;悬浮文字&lt;/text&gt;</span></span>
<span class="line"><span>    &lt;/frame&gt;</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>w.setPosition(500, 500);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>setTimeout(()=&gt;{</span></span>
<span class="line"><span>    w.close();</span></span>
<span class="line"><span>}, 2000);</span></span></code></pre></div><p>这段代码运行后将会在屏幕上显示悬浮文字, 并在两秒后消失.</p><p>有关返回的<code>FloatyRawWindow</code>对象的说明, 参见下面的<code>FloatyRawWindow</code>章节.</p><h2 id="floaty-closeall" tabindex="-1">floaty.closeAll()</h2><p>关闭所有本脚本的悬浮窗.</p><h1 id="floatywindow" tabindex="-1">FloatyWindow</h1><p>悬浮窗对象, 可通过<code>FloatyWindow.{id}</code>获取悬浮窗界面上的元素. 例如, 悬浮窗window上一个控件的id为aaa, 那么<code>window.aaa</code>即可获取到该控件, 类似于ui.</p><h2 id="window-setadjustenabled-enabled" tabindex="-1">window.setAdjustEnabled(enabled)</h2><ul><li><code>enabled</code> {boolean} 是否启用悬浮窗调整(大小、位置)</li></ul><p>如果enabled为true, 则在悬浮窗左上角、右上角显示可供位置、大小调整的标示, 就像控制台一样； 如果enabled为false, 则隐藏上述标示.</p><h2 id="window-setposition-x-y" tabindex="-1">window.setPosition(x, y)</h2><ul><li><code>x</code> {number} x</li><li><code>x</code> {number} y</li></ul><p>设置悬浮窗位置.</p><h2 id="window-getx" tabindex="-1">window.getX()</h2><p>返回悬浮窗位置的X坐标.</p><h2 id="window-gety" tabindex="-1">window.getY()</h2><p>返回悬浮窗位置的Y坐标.</p><h2 id="window-setsize-width-height" tabindex="-1">window.setSize(width, height)</h2><ul><li><code>width</code> {number} 宽度</li><li><code>height</code> {number} 高度</li></ul><p>设置悬浮窗宽高.</p><h2 id="window-getwidth" tabindex="-1">window.getWidth()</h2><p>返回悬浮窗宽度.</p><h2 id="window-getheight" tabindex="-1">window.getHeight()</h2><p>返回悬浮窗高度.</p><h2 id="window-close" tabindex="-1">window.close()</h2><p>关闭悬浮窗. 如果悬浮窗已经是关闭状态, 则此函数将不执行任何操作.</p><p>被关闭后的悬浮窗不能再显示.</p><h2 id="window-exitonclose" tabindex="-1">window.exitOnClose()</h2><p>使悬浮窗被关闭时自动结束脚本运行.</p><h1 id="floatyrawwindow" tabindex="-1">FloatyRawWindow</h1><p>原始悬浮窗对象, 可通过<code>window.{id}</code>获取悬浮窗界面上的元素. 例如, 悬浮窗window上一个控件的id为aaa, 那么<code>window.aaa</code>即可获取到该控件, 类似于ui.</p><h2 id="window-settouchable-touchable" tabindex="-1">window.setTouchable(touchable)</h2><ul><li><code>touchable</code> {Boolean} 是否可触摸</li></ul><p>设置悬浮窗是否可触摸, 如果为true, 则悬浮窗将接收到触摸、点击等事件并且无法继续传递到悬浮窗下面；如果为false, 悬浮窗上的触摸、点击等事件将被直接传递到悬浮窗下面. 处于安全考虑, 被悬浮窗接收的触摸事情无法再继续传递到下层.</p><p>可以用此特性来制作护眼模式脚本.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var w = floaty.rawWindow(</span></span>
<span class="line"><span>    &lt;frame gravity=&quot;center&quot; bg=&quot;#44ffcc00&quot;/&gt;</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>w.setSize(-1, -1);</span></span>
<span class="line"><span>w.setTouchable(false);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>setTimeout(()=&gt;{</span></span>
<span class="line"><span>    w.close();</span></span>
<span class="line"><span>}, 4000);</span></span></code></pre></div><h2 id="window-setposition-x-y-1" tabindex="-1">window.setPosition(x, y)</h2><ul><li><code>x</code> {number} x</li><li><code>x</code> {number} y</li></ul><p>设置悬浮窗位置.</p><h2 id="window-getx-1" tabindex="-1">window.getX()</h2><p>返回悬浮窗位置的X坐标.</p><h2 id="window-gety-1" tabindex="-1">window.getY()</h2><p>返回悬浮窗位置的Y坐标.</p><h2 id="window-setsize-width-height-1" tabindex="-1">window.setSize(width, height)</h2><ul><li><code>width</code> {number} 宽度</li><li><code>height</code> {number} 高度</li></ul><p>设置悬浮窗宽高.</p><p>特别地, 如果设置为-1, 则为占满全屏；设置为-2则为根据悬浮窗内容大小而定. 例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var w = floaty.rawWindow(</span></span>
<span class="line"><span>    &lt;frame gravity=&quot;center&quot; bg=&quot;#77ff0000&quot;&gt;</span></span>
<span class="line"><span>        &lt;text id=&quot;text&quot;&gt;悬浮文字&lt;/text&gt;</span></span>
<span class="line"><span>    &lt;/frame&gt;</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>w.setSize(-1, -1);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>setTimeout(()=&gt;{</span></span>
<span class="line"><span>    w.close();</span></span>
<span class="line"><span>}, 2000);</span></span></code></pre></div><h2 id="window-getwidth-1" tabindex="-1">window.getWidth()</h2><p>返回悬浮窗宽度.</p><h2 id="window-getheight-1" tabindex="-1">window.getHeight()</h2><p>返回悬浮窗高度.</p><h2 id="window-close-1" tabindex="-1">window.close()</h2><p>关闭悬浮窗. 如果悬浮窗已经是关闭状态, 则此函数将不执行任何操作.</p><p>被关闭后的悬浮窗不能再显示.</p><h2 id="window-exitonclose-1" tabindex="-1">window.exitOnClose()</h2><p>使悬浮窗被关闭时自动结束脚本运行.</p>`,84)])])}const r=e(t,[["render",i]]);export{h as __pageData,r as default};
